import 'package:geolocator/geolocator.dart';
class LocationResult {const LocationResult({this.position,this.message});final Position? position;final String? message;}
class LocationService {Future<LocationResult> current()async{if(!await Geolocator.isLocationServiceEnabled())return const LocationResult(message:'Location services are disabled. Choose a town instead.');var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied)return const LocationResult(message:'Location permission denied. You can browse using a selected town.');if(p==LocationPermission.deniedForever)return const LocationResult(message:'Location permission is permanently denied. Enable it in Settings or select a town.');try{return LocationResult(position:await Geolocator.getCurrentPosition().timeout(const Duration(seconds:12)));}catch(_){return const LocationResult(message:'Location is temporarily unavailable. Try again or select a town.');}}}
